import{_ as a,o as r,c as n,a0 as i}from"./chunks/framework.BL79I5mR.js";const p=JSON.parse('{"title":"Ranura de Preissmann dinámica","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/modificaciones-motor/04-ranura-de-preissmann-dinamica.md","filePath":"es/explanation/modificaciones-motor/04-ranura-de-preissmann-dinamica.md"}'),o={name:"es/explanation/modificaciones-motor/04-ranura-de-preissmann-dinamica.md"};function c(s,e,l,t,d,m){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="ranura-de-preissmann-dinamica" tabindex="-1">Ranura de Preissmann dinámica <a class="header-anchor" href="#ranura-de-preissmann-dinamica" aria-label="Permalink to &quot;Ranura de Preissmann dinámica&quot;">​</a></h1><h2 id="motivacion" tabindex="-1">Motivación <a class="header-anchor" href="#motivacion" aria-label="Permalink to &quot;Motivación&quot;">​</a></h2><p>La opción <code>SURCHARGE_METHOD DYNAMIC_SLOT</code> agrega un tercer método de escurrimiento en carga. El SWMM oficial ofrece dos formas de representar el escurrimiento presurizado en conductos cerrados: el algoritmo EXTRAN (perturbación tipo Hardy–Cross con $dQ/dH$) y la ranura de Preissmann estática. Ambos tienen limitaciones conocidas en los transitorios de llenado/vaciado: la ranura estática fija su ancho a partir de la profundidad instantánea, lo que en el frente de mezcla superficie libre/presión produce &quot;apretón de ranura&quot; (<em>slot squeezing</em>), una amplificación de energía artificial. La extensión <code>DYNAMIC_SLOT</code> implementa la formulación de ranura de Preissmann <em>dinámica</em> de Sharior, Hodges &amp; Vasconcelos (2023), en la que el área de la ranura evoluciona en el tiempo como un elemento de <em>almacenamiento transitorio</em>.</p><h2 id="formulacion" tabindex="-1">Formulación <a class="header-anchor" href="#formulacion" aria-label="Permalink to &quot;Formulación&quot;">​</a></h2><p>La ranura dinámica tiene un ancho superior que depende del número de Preissmann $P$ y de una celeridad de onda de presión objetivo $c_{pT}$ (el usuario la fija con <code>DPS_CELERITY</code>, por defecto 25 m/s):</p><p>$$T_s = \\frac{g,A_{\\mathrm{full}}}{c_{pT}^{2}},P^{2},$$</p><p>donde $A_{\\mathrm{full}}$ es el área de sección llena. El número de Preissmann parte, al inicio de la presurización, en</p><p>$$P_{0} = \\max!\\left(\\frac{c_{pT}}{\\alpha,c_g},\\ 1\\right), \\qquad c_g = \\sqrt{g,A_{\\mathrm{full}}/W_{\\max}},$$</p><p>con $\\alpha$ el parámetro de choque (<code>DPS_ALPHA</code>, por defecto 3) y $c_g$ la celeridad de la onda de gravedad a sección llena. El área de ranura se acumula de forma <em>dependiente de la trayectoria</em>:</p><p>$$A_s \\leftarrow \\max!\\left(A_s + T_s,\\Delta h_s,\\ 0\\right), \\qquad h_s = \\max(\\bar y - y_{\\mathrm{full}},\\ 0),$$</p><p>es decir, cada incremento de almacenamiento se crea con el ancho de ranura vigente en el momento en que se acumula, y las contribuciones previas nunca se reescriben cuando $P$ decae. Esta propiedad es la que evita la amplificación de energía del &quot;apretón de ranura&quot;. Si la carga cae bajo la clave con área residual, la carga de sobrepresión se mantiene en cero y el área restante drena a través de incrementos negativos sucesivos (histéresis de despresurización).</p><p>Después de la presurización, $P$ decae exponencialmente hacia 1 con la escala de tiempo <code>DPS_DECAY_TIME</code> ($r = 0.5$ s por defecto):</p><p>$$\\hat P(t) = 1 + (\\hat P_0 - 1)\\exp!\\left(-\\frac{10,(t - t_s)}{r}\\right),$$</p><p>con $t_s$ el instante en que el conducto entró en carga, y se suaviza espacialmente una vez por paso promediando $\\hat P$ sobre los conductos incidentes a cada nodo y tomando como $P$ de trabajo el promedio de los dos extremos del conducto.</p><h2 id="consecuencias-para-el-solver" tabindex="-1">Consecuencias para el solver <a class="header-anchor" href="#consecuencias-para-el-solver" aria-label="Permalink to &quot;Consecuencias para el solver&quot;">​</a></h2><p>Mientras una ranura está activa:</p><ul><li>el área hidráulica es $A = A_{\\mathrm{full}} + A_s$ y el ancho superior es $T_s$;</li><li>el área superficial aportada a un nodo extremo en carga es $T_s,L/4$;</li><li>el radio hidráulico se mantiene en su valor de sección llena (la ranura aporta almacenamiento pero no fricción);</li><li>las cargas de los nodos se actualizan <em>siempre</em> con la fórmula ordinaria de superficie libre; la rama de surcharge EXTRAN nunca se invoca, y la carga piezométrica sobre la clave emerge naturalmente como $z_{\\mathrm{inv}} + y_{\\mathrm{full}} + h_s$.</li></ul><p>El paso de tiempo variable usa la celeridad de presión efectiva $c_p = c_{pT}/P$ en la condición de Courant del conducto en carga:</p><p>$$\\Delta t \\le \\frac{L}{\\lvert \\bar U \\rvert + c_{pT}/P}.$$</p>',19)])])}const _=a(o,[["render",c]]);export{p as __pageData,_ as default};
